  select_sync0<=alert_select_async;select_sync1<=select_sync0;
  if(frame_start)begin
   if(!GRADED_ALERT_ENABLE)frame_alert<=0;
   else if(EVENT_ENABLE)begin if(event_advance)frame_alert<=alert_sync1;end
