glyph_rom[1022]=16'h0000;
glyph_rom[1023]=16'h0000;
end
wire [9:0] header_x=x-10'd16;
wire [9:0] ticker_x=x+scroll;
assign dynamic_text_index=ticker_x[9:4];
wire header_band=(y>=8 && y<36);
wire ticker_band=(y>=440 && y<472);
wire parameter_band=(y>=40 && y<68);
wire parameter_text=(y>=46 && y<62 && x>=16 && x<432);
wire wave_label_text=WAVE_ENABLE && (y>=310 && y<326 && x>=64 && x<128);
wire [9:0] wave_x=x-10'd64;
wire wave_band=WAVE_ENABLE && (x>=64 && x<576 && y>=332 && y<418);
wire wave_border=wave_band && (x==64 || x==575 || y==332 || y==417);
wire wave_grid=wave_band && (y==374 || y==350 || y==398 || x==192 || x==320 || x==448);
wire [8:0] wave_y,wave_prev_y;
audio_wave_snapshot u_wave(.clk(clk),.rst(rst),.frame_start(frame_start),
    .sample_valid(audio_valid),.sample(audio_sample),.read_index(wave_x[8:2]),
    .read_y(wave_y),.previous_y(wave_prev_y));
wire header_text=(y>=14 && y<30 && x>=16 && x<400);
wire ticker_text=(y>=448 && y<464);
reg [5:0] glyph_id;
reg [3:0] glyph_row,glyph_col;
reg [3:0] digit;
always @(*) begin
    glyph_id=0; glyph_row=0; glyph_col=0; digit=0;
    if(header_text) begin
        glyph_row=y-10'd14; glyph_col=header_x[3:0];
        if(header_x[9:4]<16) begin
            glyph_id=frame_mode ? emergency_label(header_x[9:4]) : normal_label(header_x[9:4]);
        end else begin
            case(header_x[9:4])
6'd16: digit=frame_time[23:20];
6'd17: digit=frame_time[19:16];
6'd19: digit=frame_time[15:12];
6'd20: digit=frame_time[11:8];
6'd22: digit=frame_time[7:4];
6'd23: digit=frame_time[3:0];
            default: digit=0;
            endcase
            glyph_id=6'd1+{2'b00,digit};
            if(header_x[9:4]==18 || header_x[9:4]==21) glyph_id=6'd11;
        end
    end else if(parameter_text) begin
        glyph_row=y-10'd46; glyph_col=header_x[3:0];
        case(frame_settings[7:6])
        2'd0: glyph_id=parameters_0(header_x[9:4]);
        2'd1: glyph_id=parameters_1(header_x[9:4]);
        2'd2: glyph_id=parameters_2(header_x[9:4]);
        default: glyph_id=parameters_3(header_x[9:4]);
        endcase
        if(header_x[9:4]==3) glyph_id=6'd1+{3'b0,frame_settings[5:3]};
        if(header_x[9:4]==12) glyph_id=6'd1+{3'b0,frame_settings[2:0]};
    end else if(wave_label_text) begin
        glyph_row=y-10'd310;glyph_col=wave_x[3:0];glyph_id=wave_label(wave_x[9:4]);
    end else if(ticker_text) begin
        glyph_row=y-10'd448; glyph_col=ticker_x[3:0];
        glyph_id=banner_label(ticker_x[9:4]);
    end
end
reg [15:0] glyph_bits;
reg [3:0] column_d;
reg band_d,text_d,mode_d,de_d,vs_d;
reg [23:0] rgb_d;
reg wave_band_d,wave_border_d,wave_grid_d,wave_join_d;
reg alert_band_d;
reg[23:0]alert_background_d,alert_ink_d;
reg [9:0] wave_pixel_y;
function [7:0] correct_channel;
input [7:0] channel;
input [2:0] brightness,contrast;
reg signed [12:0] delta,gain,offset,value;
begin
    delta=$signed({1'b0,channel})-13'sd128;
    case(contrast)
    0: gain=delta>>>1;
    1: gain=(delta+(delta<<<1))>>>2;
    3: gain=(delta+(delta<<<2))>>>2;
    4: gain=(delta+(delta<<<1))>>>1;
    default: gain=delta;
    endcase
    case(brightness)
    0: offset=-13'sd64;
    1: offset=-13'sd32;
    3: offset=13'sd32;
    4: offset=13'sd64;
    default: offset=0;
    endcase
    value=gain+13'sd128+offset;
    if(value<0) correct_channel=0;
    else if(value>255) correct_channel=255;
    else correct_channel=value[7:0];
end
endfunction
wire [2:0] active_brightness=frame_mode?3'd2:frame_settings[5:3];
wire [2:0] active_contrast=frame_mode?3'd2:frame_settings[2:0];
wire [23:0] corrected_rgb={correct_channel(in_rgb[23:16],active_brightness,active_contrast),
                          correct_channel(in_rgb[15:8],active_brightness,active_contrast),
                          correct_channel(in_rgb[7:0],active_brightness,active_contrast)};
always @(posedge clk or posedge rst) begin
    if(rst) begin
        column_d<=0; band_d<=0; text_d<=0; mode_d<=0;
        de_d<=0; vs_d<=0; rgb_d<=0;
        wave_band_d<=0;wave_border_d<=0;wave_grid_d<=0;wave_join_d<=0;wave_pixel_y<=0;
        alert_band_d<=0;alert_background_d<=0;alert_ink_d<=0;
    end else begin
        column_d<=overlay_band?overlay_col:glyph_col;
        band_d<=frame_subtitle && (header_band || parameter_band || ticker_band);
        text_d<=overlay_band?overlay_text:
         frame_subtitle && (header_text || parameter_text || ticker_text || wave_label_text); mode_d<=frame_mode;
        alert_band_d<=overlay_band;alert_background_d<=overlay_background;alert_ink_d<=overlay_ink;
        de_d<=in_de; vs_d<=in_vs; rgb_d<=corrected_rgb;
        wave_band_d<=frame_subtitle && wave_band;wave_border_d<=frame_subtitle && wave_border;wave_grid_d<=frame_subtitle && wave_grid;
        wave_join_d<=(wave_x[1:0]==0);wave_pixel_y<=y;
    end
end
// 两套ROM同步读取并在同一拍选择，保持已有像素流水线对齐。
wire use_dynamic=DYNAMIC_TEXT_ENABLE && dynamic_text_active && !frame_mode && ticker_text;
reg [15:0] dynamic_bits,static_bits;
reg dynamic_d;
always @(posedge clk)begin
 static_bits<=glyph_rom[{glyph_id,glyph_row}];
 dynamic_bits<=dynamic_font_rom[overlay_band?{overlay_glyph,overlay_row}:{dynamic_text_glyph,glyph_row}];
 dynamic_d<=use_dynamic || overlay_band;
end
always @(*)glyph_bits=dynamic_d?dynamic_bits:static_bits;
wire ink=text_d && glyph_bits[15-column_d];
function [7:0] fade_channel;
input [7:0] channel;
input [4:0] level;
reg [12:0] product;
begin product=channel*level; fade_channel=product[11:4]; end
endfunction
wire [23:0] faded_rgb={fade_channel(rgb_d[23:16],fade_level),
    fade_channel(rgb_d[15:8],fade_level),fade_channel(rgb_d[7:0],fade_level)};
wire [23:0] shaded={2'b00,faded_rgb[23:18],2'b00,faded_rgb[15:10],2'b00,faded_rgb[7:2]};
assign out_de=de_d;
assign out_vs=vs_d;
wire [8:0] wave_low=(wave_y<wave_prev_y)?wave_y:wave_prev_y;
wire [8:0] wave_high=(wave_y>wave_prev_y)?wave_y:wave_prev_y;
wire wave_ink=wave_band_d && (wave_join_d ? (wave_pixel_y>=wave_low && wave_pixel_y<=wave_high) :
    (wave_pixel_y+1>=wave_y && wave_pixel_y<=wave_y+1));
assign out_rgb= !de_d ? 24'd0 : alert_band_d ? (ink?alert_ink_d:alert_background_d) :
    ink ? (mode_d?24'hFFD060:24'hFFFFFF) :
    wave_ink ? (mode_d?24'hFFD060:24'h00FFD0) : wave_border_d ? 24'h80A0B0 :
    wave_grid_d ? 24'h304850 : (band_d || wave_band_d) ? shaded : faded_rgb;
endmodule

// I2S_receiver already outputs in the pixel clock domain. Publish only complete
// 128-sample blocks at frame boundaries, keeping the visible bank immutable.
module audio_wave_snapshot(
    input clk,rst,frame_start,sample_valid,
    input [23:0] sample,
    input [6:0] read_index,
    output [8:0] read_y,previous_y
);
reg [8:0] wave_mem[0:255];
reg [8:0] previous_mem[0:255];
reg capture_bank,display_bank,block_ready,have_snapshot;
reg [6:0] write_index;
reg [8:0] y_read,previous_read;
wire signed [9:0] amplitude=$signed({{2{sample[23]}},sample[23:16]});
wire signed [9:0] sample_position=10'sd374-amplitude;
wire [8:0] clipped_y=(sample_position<340)?9'd340:(sample_position>408)?9'd408:sample_position[8:0];
wire [6:0] previous_index=(read_index==0)?7'd0:read_index-1'b1;
assign read_y=have_snapshot?y_read:9'd374;
assign previous_y=have_snapshot?previous_read:9'd374;
always @(posedge clk) begin
    if(sample_valid && !block_ready && !rst) begin
        wave_mem[{capture_bank,write_index}]<=clipped_y;
        previous_mem[{capture_bank,write_index}]<=clipped_y;
    end
    y_read<=wave_mem[{display_bank,read_index}];
    previous_read<=previous_mem[{display_bank,previous_index}];
end
always @(posedge clk or posedge rst) begin
    if(rst) begin
        capture_bank<=1;display_bank<=0;block_ready<=0;have_snapshot<=0;write_index<=0;
    end else begin
        if(sample_valid && !block_ready) begin
            if(write_index==127) block_ready<=1;
            else write_index<=write_index+1'b1;
        end
        if(frame_start && block_ready) begin
            display_bank<=capture_bank;capture_bank<=display_bank;
            block_ready<=0;have_snapshot<=1;write_index<=0;
        end
    end
end
endmodule

// 转场步进只在场消隐更新。相接滑动等待新缓存独占读帧后提交；
// 淡入淡出保留换缓存后的消隐等待，应急取消通过读帧代次确认。
module picture_transition #(parameter SLIDE_ENABLE=0)(
    input clk,rst,frame_start,pending_async,emergency_async,
    input [1:0] mode_async,
    input bypass_async,
    input read_epoch_async,cancel_request_async,
    output [9:0] slide_offset,
    output slide_in,
    output slide_mix,
    output reg slide_epoch,cancel_ack,
    output black_ready,
    output reg [4:0] level
);
localparam IDLE=0,OUT=1,BLACK=2,SETTLE=3,IN=4,CANCEL=5;
reg [2:0] state;
reg pending_sync0,pending_sync1,emergency_sync0,emergency_sync1;
reg [1:0] settle_frames;
reg [1:0] mode_sync0,mode_sync1,active_mode;
reg bypass_sync0,bypass_sync1;
reg [9:0] shift;
reg epoch_sync0,epoch_sync1,cancel_sync0,cancel_sync1;
assign slide_offset=(SLIDE_ENABLE&&active_mode==1)?shift:10'd0;
assign slide_in=SLIDE_ENABLE&&active_mode==1&&state==IN;
assign slide_mix=SLIDE_ENABLE&&active_mode==1&&(state==OUT||state==BLACK);
// At a push endpoint, wait for a raster using only the new bank before releasing old memory.
assign black_ready=(state==BLACK)&&(!SLIDE_ENABLE||active_mode!=1||epoch_sync1==slide_epoch);
always @(posedge clk or posedge rst) begin
    if(rst) begin
        state<=IDLE;level<=16;settle_frames<=0;
        pending_sync0<=0;pending_sync1<=0;emergency_sync0<=0;emergency_sync1<=0;
        mode_sync0<=1;mode_sync1<=1;active_mode<=SLIDE_ENABLE?1:2;
        bypass_sync0<=0;bypass_sync1<=0;shift<=0;
        epoch_sync0<=0;epoch_sync1<=0;cancel_sync0<=0;cancel_sync1<=0;slide_epoch<=0;cancel_ack<=0;
    end else begin
        pending_sync0<=pending_async;pending_sync1<=pending_sync0;
        emergency_sync0<=emergency_async;emergency_sync1<=emergency_sync0;
        mode_sync0<=SLIDE_ENABLE?mode_async:2'd2;mode_sync1<=mode_sync0;
        bypass_sync0<=SLIDE_ENABLE&&bypass_async;bypass_sync1<=bypass_sync0;
        epoch_sync0<=read_epoch_async;epoch_sync1<=epoch_sync0;
        cancel_sync0<=SLIDE_ENABLE&&cancel_request_async;cancel_sync1<=cancel_sync0;
        if(frame_start) begin
            if(SLIDE_ENABLE&&state==CANCEL)begin
                if(epoch_sync1==slide_epoch)begin cancel_ack<=cancel_sync1;state<=IDLE;end
            end else if(SLIDE_ENABLE&&cancel_sync1!=cancel_ack)begin
                state<=CANCEL;shift<=0;level<=16;slide_epoch<=~slide_epoch;
            end else if(emergency_sync1||bypass_sync1) begin
                if(SLIDE_ENABLE&&slide_mix)begin state<=CANCEL;slide_epoch<=~slide_epoch;end
                else state<=IDLE;
                level<=16;settle_frames<=0;shift<=0;
            end
            else case(state)
            IDLE: if(pending_sync1) begin
                active_mode<=mode_sync1;
                if(mode_sync1==0)begin state<=BLACK;level<=16;shift<=0;end
                else if(mode_sync1==1)begin state<=OUT;level<=16;shift<=40;end
                else begin state<=OUT;level<=15;shift<=0;end
            end
            OUT: if(!pending_sync1) begin state<=IN;end
                 else if(active_mode==1)begin
                    if(shift>=600)begin shift<=640;level<=16;state<=BLACK;slide_epoch<=~slide_epoch;end
                    else shift<=shift+40;
                 end
                 else if(level==1) begin level<=0;state<=BLACK;end
                 else level<=level-1'b1;
            BLACK: if(!pending_sync1) begin
                if(active_mode==0||active_mode==1)begin state<=IDLE;level<=16;shift<=0;end
                else begin state<=SETTLE;settle_frames<=0;end
            end
            SETTLE: if(settle_frames==1) begin state<=IN;end
                    else settle_frames<=settle_frames+1'b1;
            IN: if(active_mode==1)begin
                    level<=16;
                    if(shift<=40)begin shift<=0;state<=IDLE;end
                    else shift<=shift-40;
                end
                else if(level==15) begin level<=16;state<=IDLE;end
                else level<=level+1'b1;
            default: begin state<=IDLE;level<=16;shift<=0;end
            endcase
        end
    end
end
endmodule


